/**
 * Reads one query parameter, treating a literal `?` as another `&`: some hosted
 * redirects append `?token=...` onto a callback that already carried `?state=...`,
 * yielding `state=..?token=..`. Values come back exactly as they arrived — the
 * token is a credential that round-trips through this listener verbatim.
 */
function callbackParam(query: string, key: string): string | null {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    if (separator === -1) continue;
    if (pair.slice(0, separator) === key) return pair.slice(separator + 1);
  }
  return null;
}

/** Percent-decoding for human-readable query text (OAuth error descriptions). */
function decodeQueryText(value: string): string {
  try {
    return decodeURIComponent(value.replace(/\+/g, " "));
  } catch {
    return value.replace(/\+/g, " ");
  }
}

/**
 * The Worker percent-encodes the token into the callback's query, and the
 * listener hands back what it received, so decode once before spending it as a
 * bearer credential.
 */
function decodeCallbackToken(token: string): string {
  try {
    return decodeURIComponent(token);
  } catch {
    return token;
  }
}

/** Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
 * because it lands in both the browser page and the terminal. */
function callbackFailure(query: string): string | null {
  const error = callbackParam(query, "error");
  if (!error) return null;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = callbackParam(query, "error_description");
  const decoded = description ? decodeQueryText(description) : "";
  const message = decoded
    ? decoded
    : `The login page reported an error: ${decodeQueryText(error)}`;
  return message.slice(0, 200);
}

export interface OAuthCallbackServer {
  /** The port actually bound — may differ from the requested one, see below. */
  readonly port: number;
  /** Resolves once the socket is bound and `port` has its final value. */
  ready: Promise<void>;
  /** The raw, unverified token from the callback query; rejects on error/cancel. */
  token: Promise<string>;
  close(): void;
}

/**
 * The localhost listener the browser hands the session token back to. Mirrors
 * the overlay's Rust listener (`tauri/src/main.rs`, `handle_callback_connection`)
 * minus its state check: that one generates the nonce it compares against,
 * whereas this takes only a port, so any `state` is accepted and ignored here
 * and verifying the token is left to the caller.
 *
 * Returns synchronously so the caller can read nothing but `ready` to learn
 * when the socket is up — the URL it puts in the browser depends on `port`.
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let markReady!: () => void;
  let failReady!: (error: Error) => void;
  const ready = new Promise<void>((resolve, reject) => {
    markReady = resolve;
    failReady = reject;
  });
  let resolveToken!: (token: string) => void;
  let rejectToken!: (error: Error) => void;
  const token = new Promise<string>((resolve, reject) => {
    resolveToken = resolve;
    rejectToken = reject;
  });
  // A caller that only awaits one of the two still gets the other's failure
  // reported through the one it awaits; these keep the unawaited twin from
  // surfacing as an unhandled rejection first.
  ready.catch(() => {});
  token.catch(() => {});

  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const mark = target.indexOf("?");
    const path = mark === -1 ? target : target.slice(0, mark);
    const query = mark === -1 ? "" : target.slice(mark + 1);

    const reply = (status: number, contentType: string, body: string): void => {
      response.writeHead(status, {
        "content-type": contentType,
        "content-length": Buffer.byteLength(body),
        // These URLs carry a session token — keep them out of caches and out of
        // the Referer sent to anything the page links to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
        connection: "close",
      });
      response.end(body);
    };

    if (path === "/auth/ping") {
      // The Worker's readiness probe: proves the CLI is still listening before
      // the browser is sent onward with a token.
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }
    const failure = callbackFailure(query);
    if (failure) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(failure)));
      rejectToken(new Error(failure));
      return;
    }
    const value = callbackParam(query, "token");
    if (!value) {
      const reason = "The login page came back without a session token.";
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
      rejectToken(new Error(reason));
      return;
    }
    reply(200, "text/html; charset=utf-8", signedInPage());
    resolveToken(value);
  });

  const handle = {
    port,
    ready,
    token,
    close(): void {
      server.close();
      // Replies ask for `Connection: close`, but a browser that opened a second
      // idle socket would still hold the process open.
      server.closeAllConnections?.();
    },
  };

  let retried = false;
  server.on("error", (error: NodeJS.ErrnoException) => {
    if (!retried && error.code === "EADDRINUSE" && port !== 0) {
      // Another Tui (or anything else) already owns the default port. The
      // callback URL travels with the request, so any free port works.
      retried = true;
      server.listen(0, "127.0.0.1");
      return;
    }
    const failure = error instanceof Error ? error : new Error(String(error));
    failReady(failure);
    rejectToken(failure);
  });
  server.on("listening", () => {
    const address = server.address();
    if (address && typeof address === "object") handle.port = address.port;
    markReady();
  });
  server.listen(port, "127.0.0.1");

  return handle;
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the hosted login page's redirect chain — the tab either
 * never appears or dies mid-handoff, so sign-in silently never completes.
 * Asking Arc for a real tab in a real window over AppleScript bypasses Little
 * Arc entirely. Mirrors `is_arc_bundle` in `tauri/src/main.rs`.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

function applescriptEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/** The AppleScript that opens `url` as a real tab in a real Arc/Dia window. */
export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

/**
 * Runs an opener and reports whether it actually succeeded. Spawning alone
 * can't tell us that — `xdg-open` with no handler and `open` with a broken
 * default browser both fail *after* the spawn — so we wait for the exit status.
 */
function runOpener(command: string, args: string[]): boolean {
  try {
    return spawnSync(command, args, { stdio: "ignore" }).status === 0;
  } catch {
    return false;
  }
}

/**
 * `defaults read` prints one dict per registered handler; the role and the
 * scheme are separate lines inside the same `{ ... }` block, so we scan block
 * by block for the one claiming `https`.
 */
export function parseDefaultHttpsHandler(plist: string): string | null {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block
      .split("\n")
      .find((candidate) => candidate.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) return null;
    const value = line.trim().slice("LSHandlerRoleAll = ".length).replace(/;$/, "").replace(
      /^"|"$/g,
      "",
    );
    if (value) return value;
  }
  return null;
}

/**
 * The bundle id macOS would hand an `https` URL to, read from LaunchServices.
 * Used only to detect Arc; any parse failure just means the ordinary `open`
 * path is taken.
 */
function defaultHttpsHandler(): string | null {
  const output = spawnSync(
    "defaults",
    ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"],
    { encoding: "utf8" },
  );
  if (output.status !== 0 || !output.stdout) return null;
  return parseDefaultHttpsHandler(output.stdout);
}

/**
 * Hands the sign-in URL to the user's browser. Returns false when every opener
 * we know about failed — the caller then prints the link instead of claiming a
 * browser is opening.
 */
function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    // Safari is the last resort: it is always present, so a broken or missing
    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

function requireOAuthProvider(value?: string): OAuthProvider {
  const provider = value?.toLowerCase();
  if (provider && (oauthProviders as readonly string[]).includes(provider)) {
    return provider as OAuthProvider;
  }
  throw new Error(`usage: gamepigeon auth oauth [${oauthProviders.join("|")}]`);
}

