 * localhost hand-back. The `state` nonce rides along so the Worker's redirect
 * comes back on the URL we published, not one a racing page invented.
 */
async function runOAuthLogin(provider: OAuthProvider): Promise<AuthSuccess> {
  const authBaseUrl = requireAuthBaseUrl();
