/** A provider this deployment will never sign anyone in with. */
export function unsupportedProviderPage(providers: readonly string[]): string {
  return arcadePage({
    tone: "warn",
    title: "That sign-in provider isn't supported",
    lead: `Tui signs in with ${providers.map((provider) => `<code>${escapeHtml(provider)}</code>`).join(" or ")}.`,
    steps: [
      "Run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>.",
    ],
    hint: "Prefer a password? <code>gamepigeon auth login</code> signs in the same account.",
  });
}

