cat >> test/cli-oauth.test.ts <<'EOF'

describe("a real browser session", () => {
  // Local dev shape on purpose: an http base URL means better-auth issues the
  // unprefixed `better-auth.session_token` cookie the contract names.
  const localEnv = {
    BETTER_AUTH_URL: "http://localhost:8787",
    BETTER_AUTH_TRUSTED_ORIGINS: "http://127.0.0.1:3210,http://localhost:8787",
    MIGRATION_SECRET: "test-only-migration-secret",
  };

  async function localFetch(path: string, init: RequestInit = {}): Promise<Response> {
    return worker.fetch(new Request(`http://localhost:8787${path}`, init), {
      ...env,
      ...localEnv,
    });
  }

  test("is handed to the local listener with its query preserved", async () => {
    const migrated = await localFetch("/migrate", {
      method: "POST",
      headers: { authorization: `Bearer ${localEnv.MIGRATION_SECRET}` },
    });
    expect(migrated.status).toBe(200);

    const signUp = await localFetch("/api/auth/sign-up/email", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        email: "handoff@example.test",
        password: "correct-horse-battery-staple",
        name: "Handoff",
      }),
    });
    expect(signUp.status).toBe(200);
    const cookie = signUp.headers
      .getSetCookie()
      .map((value) => value.split(";")[0]!)
      .find((value) => value.startsWith("better-auth.session_token="));
    expect(cookie).toBeDefined();
    const token = decodeURIComponent(cookie!.slice("better-auth.session_token=".length));

    const handoff = await localFetch(`/cli/handoff?next=${encodeURIComponent(localNext)}`, {
      headers: { cookie: cookie! },
    });

    expect(handoff.status).toBe(200);
    expect(handoff.headers.get("cache-control")).toBe("no-store");
    const target = new URL(`http://127.0.0.1:3210/auth/callback?state=nonce`);
    target.searchParams.set("token", token);
    expect(await handoff.text()).toContain(`location.replace(${JSON.stringify(target.toString())})`);
  });
});
EOF
