path = "test/cli-oauth.test.ts"
src = open(path).read()
marker = """  test.each([
    ["a public https target", "https://evil.example/steal"],
    ["another host over http", "http://evil.example/steal"],
    ["a host that only looks local", "http://127.0.0.1.evil.example/steal"],"""
addition = '''  test("sends a configured provider into its consent screen, state cookie and all", async () => {
    const response = await get(`/cli/oauth?provider=google&next=${encodeURIComponent(localNext)}`, {
      env: withGoogle,
    });

    expect(response.status).toBe(302);
    const location = new URL(response.headers.get("location") ?? "");
    expect(location.origin + location.pathname).toBe(
      "https://accounts.google.com/o/oauth2/v2/auth",
    );
    expect(location.searchParams.get("client_id")).toBe(withGoogle.GOOGLE_CLIENT_ID);
    // The provider redirect comes back to the Worker, never to the listener: the
    // client secret and the code exchange stay server-side.
    expect(location.searchParams.get("redirect_uri")).toBe(
      "https://auth.runretroarcade.com/api/auth/callback/google",
    );
    expect(response.headers.get("cache-control")).toBe("no-store");
    // State lives in a cookie here, so the redirect has to carry it along.
    expect(response.headers.getSetCookie().join(" ")).toContain("oauth_state=");
  });

'''
assert marker in src
src = src.replace(marker, addition + marker, 1)
open(path, "w").write(src)
PY
timeout 400 npm test 2>&1 | tail -6

